class RetainedOriginal:
    def __init__(self, iterator, kind, reached, retained, code):
        self.iterator,self.kind,self.reached,self.started=iterator,kind,reached,False
        retained.append((self,iterator,code))
    def __iter__(self):return self
    def __next__(self):return self.send(None)
    def send(self,value):
        if not self.started:
            self.started=True
            if self.kind in self.reached:self.reached[self.kind]+=1
        return self.iterator.send(value)
    def throw(self,*args):return self.iterator.throw(*args)
    def close(self):return self.iterator.close()

@contextmanager
def reference(retained=None):
    retained=[] if retained is None else retained
    namespace={'__name__':language.__name__,'__package__':'chaos'}
    exec(compile(ORIGINAL,__file__+':original_s_execute','exec'),namespace)
    compiled=namespace['_s_execute']
    old=FunctionType(compiled.__code__,vars(language),compiled.__name__,compiled.__defaults__,compiled.__closure__)
    old.__kwdefaults__=compiled.__kwdefaults__
    reached={kind:0 for kind in KINDS}
    def invoke(e,node,*args,**kwargs):
        return RetainedOriginal(old(e,node,*args,**kwargs),node[0],reached,retained,old.__code__)
    with patch.object(language.Evaluator,'_s_execute',invoke):yield reached
